"""Conditional flow matching: t=0 is noise and t=1 is data."""
import torch
from torch import Tensor
from typing import Callable


def sample_t(batch: int, generator: torch.Generator | None, dist: str = "uniform", m: float = 0.0, s: float = 1.0) -> Tensor:
    """[B] strictly in (0,1); logit_normal uses sigmoid(N(m,s²))."""
    if dist == "uniform":
        t = torch.rand(batch, generator=generator)
    elif dist == "logit_normal":
        t = (m + s * torch.randn(batch, generator=generator)).sigmoid()
    else:
        raise ValueError("dist must be uniform or logit_normal")
    return t.clamp(torch.finfo(t.dtype).eps, 1 - torch.finfo(t.dtype).eps)


def interpolate(x0: Tensor, x1: Tensor, t: Tensor) -> Tensor:
    """Broadcast t [B] to x0/x1 [B,...]."""
    time = t.reshape(-1, *([1] * (x0.ndim - 1)))
    return (1 - time) * x0 + time * x1


def cfm_target(x0: Tensor, x1: Tensor) -> Tensor:
    """Conditional velocity [B,...] along the linear interpolation."""
    return x1 - x0


def cfm_loss(model: Callable[[Tensor, Tensor], Tensor], x1: Tensor, x0: Tensor, t: Tensor) -> Tensor:
    """Scalar elementwise mean squared velocity error; x0 is noise."""
    return (model(interpolate(x0, x1, t), t) - cfm_target(x0, x1)).square().mean()


@torch.no_grad()
def euler_sample(model: Callable[[Tensor, Tensor], Tensor], x0: Tensor, num_steps: int, return_traj: bool = False) -> Tensor | tuple[Tensor, Tensor]:
    """Evaluate t=k/n only, k=0..n-1; optional (samples,[n+1,B,D]) trajectory."""
    if num_steps < 1:
        raise ValueError("num_steps must be positive")
    x = x0.clone()
    trajectory = [x.clone()] if return_traj else None
    for k in range(num_steps):
        t = torch.full((len(x),), k / num_steps, dtype=x.dtype, device=x.device)
        x = x + model(x, t) / num_steps
        if return_traj:
            trajectory.append(x.clone())
    return (x, torch.stack(trajectory)) if return_traj else x

import torch
from torch import Tensor


def sample_student(transition_logits: Tensor, batch_size: int, length: int,
                   generator: torch.Generator) -> tuple[Tensor, Tensor]:
    """Fixed-length Markov language model: row V is BOS, rows 0..V-1 are tokens."""
    if transition_logits.ndim != 2 or transition_logits.shape[0] != transition_logits.shape[1] + 1:
        raise ValueError('transition_logits must have shape [vocab + 1, vocab]')
    if batch_size < 1 or length < 1:
        raise ValueError('batch_size and length must be positive')
    with torch.no_grad():
        vocab = transition_logits.shape[-1]
        previous = torch.full((batch_size,), vocab, device=transition_logits.device, dtype=torch.long)
        tokens, prefixes = [], []
        for _ in range(length):
            prefixes.append(previous)
            probabilities = transition_logits[previous].softmax(-1)
            previous = torch.multinomial(probabilities, 1, generator=generator).squeeze(-1)
            tokens.append(previous)
        return torch.stack(tokens, -1), torch.stack(prefixes, -1)


def distillation_loss(student_logits: Tensor, teacher_logits: Tensor, mask: Tensor,
                       direction: str = 'reverse') -> Tensor:
    """Full-vocabulary KL at student-generated prefixes; valid-token average."""
    if direction not in ('reverse', 'forward'):
        raise ValueError('direction must be reverse or forward')
    active = mask.bool().unsqueeze(-1)
    student = torch.where(active, student_logits, torch.zeros_like(student_logits)).log_softmax(-1)
    teacher = torch.where(active, teacher_logits.detach(), torch.zeros_like(teacher_logits)).log_softmax(-1)
    if direction == 'reverse':
        divergence = (student.exp() * (student - teacher)).sum(-1)
    else:
        divergence = (teacher.exp() * (teacher - student)).sum(-1)
    return (divergence * mask).sum() / mask.sum().clamp_min(1)

import torch
from torch import Tensor


def lora_delta(a: Tensor, b: Tensor, alpha: float = 1.0) -> Tensor:
    """A [r,in], B [out,r] -> delta W [out,in], scaled by alpha/r."""
    if a.ndim != 2 or b.ndim != 2 or a.shape[0] < 1 or a.shape[0] != b.shape[1]:
        raise ValueError('A and B must be rank-compatible matrices with positive rank')
    return (b @ a) * (alpha / a.shape[0])


def lora_linear(x: Tensor, weight: Tensor, a: Tensor, b: Tensor,
                alpha: float = 1.0, bias: Tensor | None = None) -> Tensor:
    """Frozen base and bias; gradients still flow to x and both adapters."""
    base = torch.nn.functional.linear(x, weight.detach(), None if bias is None else bias.detach())
    return base + torch.nn.functional.linear(x, lora_delta(a, b, alpha))

