import torch
from torch import Tensor


def _time(t: Tensor, x: Tensor) -> Tensor:
    return t.reshape(-1, *([1] * (x.ndim - 1)))


def meanflow_target(model, z: Tensor, r: Tensor, t: Tensor, velocity: Tensor) -> tuple[Tensor, Tensor]:
    """Model arguments are (z, r, t); r <= t, t=0 data, t=1 noise."""
    prediction, derivative = torch.func.jvp(model, (z, r, t), (velocity, torch.zeros_like(r), torch.ones_like(t)))
    target = (velocity - _time(t - r, z) * derivative).detach()
    return prediction, target


def meanflow_loss(model, clean: Tensor, noise: Tensor, r: Tensor, t: Tensor) -> Tensor:
    """Unweighted MSE core (adaptive loss weighting is outside this module)."""
    z = (1 - _time(t, clean)) * clean + _time(t, clean) * noise
    prediction, target = meanflow_target(model, z, r, t, noise - clean)
    return (prediction - target).square().mean()


@torch.no_grad()
def one_step(model, noise: Tensor) -> Tensor:
    """One model call: z_0 = z_1 - u(z_1, 0, 1)."""
    r = noise.new_zeros(len(noise)); t = noise.new_ones(len(noise))
    return noise - model(noise, r, t)

import torch
from torch import Tensor


def _time(t: Tensor, x: Tensor) -> Tensor:
    return t.reshape(-1, *([1] * (x.ndim - 1)))


def make_noisy(clean: Tensor, noise: Tensor, t: Tensor) -> Tensor:
    """z_t=t*x+(1-t)*epsilon, t=0 noise and t=1 clean."""
    time = _time(t, clean)
    return time * clean + (1 - time) * noise


def prediction_to_velocity(prediction: Tensor, z: Tensor, t: Tensor, kind: str = 'x', eps: float = .01) -> Tensor:
    """Map x/eps/v predictions to velocity; clamp each denominator at eps."""
    time = _time(t, z)
    if kind == 'x':
        return (prediction - z) / (1 - time).clamp_min(eps)
    if kind == 'eps':
        return (z - prediction) / time.clamp_min(eps)
    if kind == 'v':
        return prediction
    raise ValueError('kind must be x, eps or v')


def velocity_loss(prediction: Tensor, clean: Tensor, noise: Tensor, t: Tensor, kind: str = 'x', eps: float = .01) -> Tensor:
    """All prediction types use velocity-space MSE, matching the x-code clamped target."""
    z = make_noisy(clean, noise, t)
    target = (clean - z) / (1 - _time(t, z)).clamp_min(eps)
    return (prediction_to_velocity(prediction, z, t, kind, eps) - target).square().mean()

